import { mageSlug } from "@/core/routing/builderPath";
import type { Card, Mage, Spellbook } from "@/core/rules/types";
import cardsJson from "./cards.json";
import { mages as mageList } from "./mages";

// Generated by `npm run data`; the JSON widens literal unions to string.
export const cards = cardsJson as Card[];

export const cardsById: ReadonlyMap<string, Card> = new Map(
  cards.map((card) => [card.id, card]),
);

export const cardsByCode: ReadonlyMap<string, Card> = new Map(
  cards.map((card) => [card.code, card]),
);

export const mages: Mage[] = mageList;

export const magesById: ReadonlyMap<string, Mage> = new Map(
  mages.map((mage) => [mage.id, mage]),
);

/** Mages by the URL slug of their name, such as "sistarran-wizard". */
export const magesBySlug: ReadonlyMap<string, Mage> = new Map(
  mages.map((mage) => [mageSlug(mage.name), mage]),
);

/**
 * The spellbook's mage, or undefined when it has none or names one not in the
 * catalog.
 */
export const spellbookMage = (spellbook: Spellbook): Mage | undefined => {
  if (spellbook.mageId === null) {
    return undefined;
  }

  return magesById.get(spellbook.mageId);
};
